declare(strict_types=1);
require_once __DIR__.'/TestDatabase.php';
use PHPUnit\Framework\TestCase;
use Sexogate\{Fixtures,Principal,ShoppingCart,Cart,Commerce,RuleViolation};
final class ShoppingCartTest extends TestCase
{
    private function shop():array{$f=new TestDatabase();$a=new Principal('admin','admin',true);$x=new Fixtures($f->db,$f->config);$x->policies();$x->catalog($a);$ids=array_column($f->db->all('SELECT id,sku FROM variants ORDER BY sku'),'id','sku');return [$f,new ShoppingCart($f->db,$f->config),bin2hex(random_bytes(32)),$ids];}
    public function testAddingAccumulatesWithoutSilentlyCappingAndStaleWritesFail():void
    {[$f,$s,$token,$ids]=$this->shop();$a=$s->command($token,['action'=>'add','variantId'=>$ids['TEST-01'],'quantity'=>2]);$b=$s->command($token,['action'=>'add','variantId'=>$ids['TEST-01'],'quantity'=>3]);self::assertSame(5,$b['items'][0]['quantity']);try{$s->command($token,['action'=>'set','variantId'=>$ids['TEST-01'],'quantity'=>1,'revision'=>$a['revision']]);self::fail('Eski sepet güncel sepeti ezdi.');}catch(RuleViolation $e){self::assertSame('CART_CHANGED',$e->rule);}self::assertSame(5,(new Cart($f->db,$f->config))->get($token)['items'][0]['quantity']);}
    public function testRemovalUndoIsSingleUseBoundToTheCartAndUnchangedPostState():void
    {[$f,$s,$token,$ids]=$this->shop();$c=$s->command($token,['action'=>'add','variantId'=>$ids['TEST-01'],'quantity'=>2]);$r=$s->command($token,['action'=>'clear','revision'=>$c['revision']]);self::assertCount(0,$r['items']);$restored=$s->command($token,['action'=>'undo','undoToken'=>$r['undoToken']]);self::assertSame(2,$restored['items'][0]['quantity']);try{$s->command($token,['action'=>'undo','undoToken'=>$r['undoToken']]);self::fail('Geri alma ikinci kez kullanıldı.');}catch(RuleViolation $e){self::assertSame('UNDO_UNAVAILABLE',$e->rule);}}
    public function testExpiryOtherCartAndInterveningChangePreventUndo():void
    {[$f,$s,$token,$ids]=$this->shop();$c=$s->command($token,['action'=>'add','variantId'=>$ids['TEST-01'],'quantity'=>1]);$r=$s->command($token,['action'=>'clear','revision'=>$c['revision']]);try{$s->command(bin2hex(random_bytes(32)),['action'=>'undo','undoToken'=>$r['undoToken']]);self::fail('Başka sepet geri alındı.');}catch(RuleViolation){}$s->command($token,['action'=>'add','variantId'=>$ids['TEST-02'],'quantity'=>1]);try{$s->command($token,['action'=>'undo','undoToken'=>$r['undoToken']]);self::fail('Aradaki değişiklik ezildi.');}catch(RuleViolation $e){self::assertSame('CART_CHANGED',$e->rule);}$f->db->execute('UPDATE cart_undo SET expires_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 SECOND)');$this->expectException(RuleViolation::class);$s->command($token,['action'=>'undo','undoToken'=>$r['undoToken']]);}
    public function testVariantReplacementMergesOnlyVariantsOfTheSameProduct():void
    {[$f,$s,$token,$ids]=$this->shop();$source=$f->db->one('SELECT * FROM variants WHERE id=?',[$ids['TEST-01']]);$target='same-product-option';$f->db->execute("INSERT INTO variants(id,product_id,sku,name,name_en,price_minor,cost_minor,tax_class) VALUES(?,?,?,'Krem','Cream',14900,0,'*')",[$target,$source['product_id'],'TEST-CREAM']);$f->db->execute("INSERT INTO inventory_balance(variant_id,warehouse_id,on_hand) VALUES(?,'main',10)",[$target]);$s->command($token,['action'=>'add','variantId'=>$target,'quantity'=>3]);$c=$s->command($token,['action'=>'add','variantId'=>$ids['TEST-01'],'quantity'=>2]);$r=$s->command($token,['action'=>'replace','variantId'=>$ids['TEST-01'],'targetVariantId'=>$target,'revision'=>$c['revision']]);self::assertCount(1,$r['items']);self::assertSame(5,$r['items'][0]['quantity']);$this->expectException(RuleViolation::class);$s->command($token,['action'=>'replace','variantId'=>$target,'targetVariantId'=>$ids['TEST-02'],'revision'=>$r['revision']]);}
    public function testOnlySelectedLinesEnterCheckoutAndPaymentKeepsTheOthers():void
    {[$f,$s,$token,$ids]=$this->shop();$s->command($token,['action'=>'add','variantId'=>$ids['TEST-01'],'quantity'=>1]);$c=$s->command($token,['action'=>'add','variantId'=>$ids['TEST-02'],'quantity'=>2]);$r=$s->command($token,['action'=>'select','variantIds'=>[$ids['TEST-01']],'revision'=>$c['revision']]);self::assertSame(14900,$r['subtotalMinor']);$commerce=new Commerce($f->db,$f->config);$i=['email'=>'cart@example.invalid','fullName'=>'Hamza ÖZBALKAN','phone'=>'05000000000','line1'=>'Şişli Çeşme adresi','city'=>'İstanbul','postalCode'=>'34000','privacyAccepted'=>true,'termsAccepted'=>true,'idempotencyKey'=>bin2hex(random_bytes(16))];$i['quoteToken']=$commerce->quote($token,$i)['quoteToken'];$o=$commerce->checkout($token,$i);self::assertSame(1,(int)$f->db->one('SELECT COUNT(*) n FROM order_items WHERE order_id=?',[$o['orderId']])['n']);$e=$commerce->testEvent($o['orderId'],$o['trackingToken'],'succeeded');$commerce->handleTest($e['raw'],$e['signature']);$remaining=(new Cart($f->db,$f->config))->get($token);self::assertCount(1,$remaining['items']);self::assertSame($ids['TEST-02'],$remaining['items'][0]['variantId']);}
    public function testAccountMergeCannotSilentlyDiscardQuantitiesOverTheLimit():void
    {[$f,$s,$first,$ids]=$this->shop();$v=$ids['TEST-01'];(new \Sexogate\Inventory($f->db,$f->config))->receive($v,100,'İzole birleştirme sınır kabulü',bin2hex(random_bytes(16)),new Principal('admin','admin',true));$f->db->execute("INSERT INTO `user`(id,name,email,emailVerified,role) VALUES('merge-user','İzole üye','merge-limit@example.invalid',true,'customer')");$second=bin2hex(random_bytes(32));$target=bin2hex(random_bytes(32));$s->command($first,['action'=>'add','variantId'=>$v,'quantity'=>60]);$s->command($second,['action'=>'add','variantId'=>$v,'quantity'=>50]);$c=new \Sexogate\Customers($f->db,$f->config);$c->mergeCart($first,$target,'merge-user');try{$c->mergeCart($second,bin2hex(random_bytes(32)),'merge-user');self::fail('Adet sessizce99a kesildi.');}catch(RuleViolation $e){self::assertSame('CART_MERGE_LIMIT',$e->rule);}self::assertSame(60,(new Cart($f->db,$f->config))->get($target,'TRY','merge-user')['items'][0]['quantity']);self::assertSame(50,(new Cart($f->db,$f->config))->get($second)['items'][0]['quantity']);}
}
